assert len(first)==25 and sum(d['duration'] for d in first)==120
(ROOT/'content/course.json').write_text(json.dumps(SESSIONS,ensure_ascii=False,indent=2)+'\n')
for s in SESSIONS:
    p=ROOT/'docs'/f'session-{s["id"]}-instructor.md'
    lines=[f'# راهنمای مدرس — {s["title"]}', '', 'مدت: ۱۲۰ دقیقه؛ زمان اختصاصی هر اسلاید در زیر آمده است. فعالیت‌های عملی در زمان همین اسلایدها انجام می‌شوند، نه علاوه بر آن. پیش از کلاس نصب ابزارها را طبق راهنمای آزمایشگاه انجام دهید.','', 'در صورت نیاز به استراحت، پنج دقیقه از بخش بحث پایانی کم کنید و آن را در زمان جلسه ثبت کنید.','']
    elapsed=0
    for i,slide in enumerate(s['slides']):
        lines += [f'## {i+1}. {slide["title"]} — دقیقهٔ {elapsed} تا {elapsed+slide['duration']}', '', *['- '+x for x in slide['points']], '', '**راهنمای اجرا و بحث:** '+slide['notes'],'']
        elapsed += slide['duration']
        if slide.get('comparison'):
            table=slide['comparison']
            lines += ['**'+table['caption']+'**','', '| '+' | '.join(table['headings'])+' |', '| '+' | '.join(['---']*len(table['headings']))+' |']
            lines += ['| '+' | '.join(row)+' |' for row in table['rows']]
            lines += ['']
        if s['id']==1 and slide.get('code'):
            lines += ['```text',slide['code'],'```','']
        if s['id']==2 and i==2:
            lines += ['```text',slide['code'],'```','']
        if s['id']==2 and i==3:
            quiz=slide['quiz']
            lines += ['**تمرین کلاسی:** '+quiz['question'],'', *['- '+option for option in quiz['options']], '', '**پاسخ و دلیل:** '+quiz['options'][quiz['answer']]+' — '+quiz['explanation'],'']
        if slide.get('sources'):
            lines += ['منابع: '+ '، '.join('['+source['title']+']('+source['url']+')' for source in slide['sources']), '']
    lines += ['## معیار ارزیابی','قرارداد و توضیح تصمیم: ۲۵٪؛ اجرای تمرین و آزمون: ۴۰٪؛ تشخیص خطا و بازیابی: ۲۰٪؛ گزارش شواهد و محدودیت: ۱۵٪.','',f'راهنمای تمرین و پاسخ: [آزمایشگاه جلسه](../labs/session-{s["id"]}/README.md)']
    p.write_text('\n'.join(lines)+'\n')
print(f'Authored {len(SESSIONS)} sessions / {sum(len(s["slides"]) for s in SESSIONS)} slides / {sum(s["duration"] for s in SESSIONS)} minutes')
